━━━━━━━━━━━━━━━━━━━━━━
　押しボタンスイッチは押している間だけ接点が変わるので、そのままでは手を離すと電動機が止まってしまいます。そこで、電磁接触器の補助接点（メーク接点）を始動ボタンと並列に入れておき、いったん投入されたら自分自身の接点で電源を保ち続けるようにします。これを自己保持回路といいます。★
・始動ボタンは通常開（a接点）、停止ボタンは通常閉（b接点）を使う★
