・熱動継電器の接点は操作回路に直列に入れ、動作したときに自己保持を解除する
・押しボタンの色は、始動が緑または黒、停止が赤とするのが一般的
・電動機の外箱には接地工事を施す。300V以下ならD種接地工事、300Vを超えるならC種接地工事★
・屋外や湿気の多い場所では、防まつ形や全閉外扇形の電動機を選ぶ

━━━━━━━━━━━━━━━━━━━━━━
