        body: `▼ゼロから：鉄心の中で磁束を共有して電圧を作り変える
　発電所で作られた電気は数万ボルトから数十万ボルトで送られ、電柱の上で6600Vになり、柱上変圧器で100Vや200Vに下げられて家に届きます。この電圧を変える機器が変圧器（トランス）です。動く部分がまったくないのに電圧を自在に変えられる、電気工学のなかでも特に美しい装置です。
　構造は、環状や日の字形の鉄心に、一次巻線と二次巻線を巻いただけ。一次側に交流電圧を加えると、鉄心の中に交番磁束ができます。この磁束は鉄心を通って二次巻線も貫くので、二次巻線に起電力が誘導されます。電磁誘導そのものです。二次巻線の巻数が一次の半分なら、誘導される電圧も半分になります。つまり巻数の比がそのまま電圧の比になるのです。
　ここで大事なのは、変圧器は交流でしか働かないという点です。直流を加えると磁束が変化しないので二次には何も出ず、それどころか一次巻線が過熱して焼損します。試験でも「直流では使えない」は頻出です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 巻数比と電圧・電流の関係
━━━━━━━━━━━━━━━━━━━━━━
　式　V1 ÷ V2 ＝ N1 ÷ N2 ＝ a
　　V1…一次電圧　V2…二次電圧　N1…一次巻数　N2…二次巻数　a…巻数比
　電流は電圧と逆の比になります。入力と出力の電力がほぼ等しいからです。
　式　I1 ÷ I2 ＝ N2 ÷ N1 ＝ 1 ÷ a
　まとめると、電圧は巻数に比例し、電流は巻数に反比例します。★
　式　V1 × I1 ＝ V2 × I2（損失を無視した場合）

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算の実例
━━━━━━━━━━━━━━━━━━━━━━
　例1　一次巻数1000回、二次巻数50回、一次電圧6600Vのときの二次電圧
　　V2 ＝ V1 × N2 ÷ N1
　　V2 ＝ 6600 × 50 ÷ 1000
　　V2 ＝ 330 V
　例2　一次6600V、二次210V、二次電流100Aのときの一次電流
　　巻数比　a ＝ 6600 ÷ 210 ＝ 31.4
　　I1 ＝ I2 ÷ a
　　I1 ＝ 100 ÷ 31.4
　　I1 ＝ 3.18 A
　例3　一次200V、二次100V、二次側に20Aが流れているときの一次電流
　　I1 ＝ 20 × 100 ÷ 200
　　I1 ＝ 10 A
　→ 電圧が半分なら電流は2倍、という関係を身体で覚えてしまうこと★

【図解】変圧器で比例するもの・反比例するもの
　量｜一次と二次の関係｜覚え方
　電圧｜巻数に比例｜巻数が多い側が高電圧★
　電流｜巻数に反比例｜高電圧側は電流が小さい★
　電力｜ほぼ等しい｜損失ぶんだけ二次が小さい
　周波数｜変化しない｜変圧器は周波数を変えない★
　⇒ 変圧器は電圧と電流を変換するが、周波数と電力は変えない
　⇒ 高圧側は細い電線、低圧側は太い電線になる理由もここにある
　⚠ 「変圧器は周波数も変換できる」は誤り

━━━━━━━━━━━━━━━━━━━━━━
🔑 変圧器の構造と各部の名称
━━━━━━━━━━━━━━━━━━━━━━
・鉄心…けい素鋼板を薄く重ねた成層鉄心。磁束の通り道になる
・巻線…一次巻線と二次巻線。銅線に絶縁を施したもの
・タップ…一次巻線の途中から引き出した端子。電源電圧が高めまたは低めの地域で、二次電圧を適正に保つために切り換える★
・ブッシング…外箱から電線を引き出す部分の絶縁物
・絶縁油…油入変圧器の内部を満たす。絶縁と冷却の二役★
・コンサベータ…油の膨張収縮を吸収するタンク
　→ モールド変圧器は絶縁油を使わず、巻線を樹脂で固めたもの。難燃性で屋内に適する★
・柱上変圧器は、電柱の上で6600Vを単相3線式105V／210Vに降圧する。二次側の中性点は接地する
・単相3線式の変圧器では、中性線に接地工事を施すことで、混触時に低圧側の電圧が異常上昇するのを防ぐ★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「変圧器は直流電圧も変圧できる」→ ×。交流専用★
・「電流は巻数に比例する」→ ×。反比例
・「変圧器は周波数を変える」→ ×。変えない★
・単巻変圧器は一次と二次で巻線の一部を共用する構造。小形軽量だが一次と二次が電気的に絶縁されない
・変圧器の絶縁油は、絶縁と冷却の二つの役割を持つ★
・三相の変圧は、単相変圧器3台をデルタデルタやスターデルタに結線するか、三相変圧器1台で行う

★ここだけ暗記
・V1 ÷ V2 ＝ N1 ÷ N2、I1 ÷ I2 ＝ N2 ÷ N1★
・電圧は巻数に比例、電流は反比例★
・変圧器は交流専用。直流では働かない
・周波数は変わらない`,
