・自動点滅器…内部の光電素子で周囲の明るさを検出し、暗くなると点灯させる。屋外灯に使う。傍記A★
・タイムスイッチ…設定した時刻に入切する。傍記T★
・熱線式自動スイッチ（人感センサ）…人の出す赤外線を検出して自動で点灯し、一定時間後に消灯する
