　パイロットランプ（表示灯）は、埋込連用取付枠にスイッチと並べて取り付ける小さなランプです。技能試験の候補問題にも必ず含まれ、筆記の配線図問題でも複線図を書かせる形で出ます。難しく感じるのは、同じ見た目のランプでも、結線の仕方によって点灯の仕方が三通りに変わるからです。まずこの三通りを名前で区別しましょう。
　ひとつめが常時点灯。スイッチの状態に関係なく、電源が生きているかぎり常に点灯します。ふたつめが同時点滅。スイッチを入れると負荷と同時に点灯し、切ると同時に消えます。みっつめが異時点滅。スイッチを切っているときに点灯し、入れると消えます。位置表示灯内蔵スイッチと同じ動きです。
　この節では常時点灯を扱います。三つのなかでいちばん結線が単純で、複線図を書くときの基準にもなります。

