　異時点滅は、負荷が消えているときにパイロットランプが点灯し、負荷が点いているときにランプが消える結線です。「異なる時に点滅する」という名のとおり、負荷とランプの点灯タイミングが逆になります。位置表示灯内蔵スイッチ（傍記H）と同じ働きで、暗い場所でスイッチの位置を知らせるのが目的です。
