　動作を追ってみましょう。スイッチが切のとき、電流はランプを通り、さらに負荷を通って接地側へ流れます。ランプと負荷が直列になった状態です。ランプは抵抗が非常に大きいので、電圧のほとんどがランプにかかり、ランプだけがほのかに点灯します。負荷にはごくわずかな電流しか流れないので、照明なら光りません。スイッチを入れると、ランプの両端が短絡されるのでランプは消え、負荷に全電圧がかかって点灯します。

