        id: 'd2-ki-31', title: '電線の接続の原則と接続方法', emoji: '🔗',
        body: `▼ゼロから：接続部は電気設備のいちばん弱いところ
　電気事故の原因を調べると、電線の接続部が発端であることが非常に多いことがわかっています。接続がゆるいと、そこだけ抵抗が大きくなり、電流が流れるたびに発熱します。発熱すると金属が酸化してさらに抵抗が増え、やがて赤熱して火災に至ります。これをトラッキングや接触不良による発熱といいます。
　だからこそ、電気設備技術基準の解釈では、電線の接続について細かい決まりが定められています。第二種電気工事士の試験では、この接続の原則が繰り返し出題されます。文言をそのまま覚えるのではなく、なぜそう決められているのかを理解すれば、選択肢を見ただけで判断できるようになります。
　原則はおおむね四つです。電気抵抗を増加させないこと。引張強さを著しく減少させないこと（20パーセント以上減少させない）。接続部分に絶縁電線と同等以上の絶縁効力のある処置をすること。接続器やろう付けを用いること。この四つを軸に整理していきましょう。★

━━━━━━━━━━━━━━━━━━━━━━
🔑 電線接続の四原則
━━━━━━━━━━━━━━━━━━━━━━
・電気抵抗を増加させないこと★
　→ 接続部の抵抗が増えると発熱の原因になる
・電線の引張強さを20パーセント以上減少させないこと★
　→ ねじって細くなったり傷が入ったりすると強度が落ちる
・接続部分には、接続管その他の器具を使うか、ろう付けすること★
　→ ただし、より線をリングスリーブで圧着するのは器具を使う接続にあたる
・接続部分は、絶縁電線の絶縁物と同等以上の絶縁効力のあるもので被覆すること★
　→ ビニルテープなら半幅重ねで2回以上（4層以上）巻く
　→ 差込形コネクタやリングスリーブ用絶縁キャップを使ってもよい
・裸電線どうしの接続や、コード相互の接続には、それぞれ定められた接続器を使う

━━━━━━━━━━━━━━━━━━━━━━
🔑 接続の方法
━━━━━━━━━━━━━━━━━━━━━━
・リングスリーブによる圧着接続…もっとも一般的。リングスリーブ用圧着ペンチで圧着する★
・差込形コネクタによる接続…電線を差し込むだけ。すばやく確実。単線専用のものが多い★
・ねじり接続（ツイスト接続）…電線どうしをねじり合わせ、はんだ付けしてテープを巻く。現在はほとんど使わない
・とも巻き接続、ブリタニア接続…古典的な手作業の接続
・圧着端子による接続…機器の端子ねじに接続するときに用いる★
・電線コネクタ、ボルト形コネクタ…太い電線の接続に使う
・接続部分は必ずボックスの中に収める★
　→ 天井裏や壁の中に、むき出しのまま接続部を放置してはならない
　→ 点検できるようにしておくことも重要

━━━━━━━━━━━━━━━━━━━━━━
🔑 施工上の注意
━━━━━━━━━━━━━━━━━━━━━━
・被覆をむく長さは、使用する接続器具の指定に従う★
・電線に傷（切り込み）を入れると、そこから折れる。ワイヤストリッパを使うと確実
・銅とアルミのように異種金属を直接接続すると、電食が起きて劣化する。専用の接続器を使う★
・接続部を引っ張って抜けないことを確認する
・より線と単線を接続するときは、それぞれに適した接続器を選ぶ
・接続部が多いほど故障の可能性が増えるので、必要以上に接続点を作らない★

【図解】電線接続の原則
　原則｜内容｜理由
　抵抗｜増加させない★｜発熱と火災の防止
　強度｜20パーセント以上減少させない★｜断線の防止
　絶縁｜同等以上の絶縁効力★｜漏電と感電の防止
　器具｜接続器またはろう付け★｜確実な接続の確保
　⇒ 接続部は必ずボックス内に収める★
　⇒ テープ巻きは半幅重ねで2回以上
　⚠ 「引張強さを50パーセント以上減少させない」は誤り。20パーセント

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「電線の引張強さは30パーセント以上減少させないこと」→ ×。20パーセント★
・「接続部分は絶縁テープを1回巻けばよい」→ ×。同等以上の絶縁効力が必要★
・「接続部分は壁の中に隠してよい」→ ×。ボックス内に収める★
・「電線の接続にはろう付けが必ず必要」→ ×。接続器を使えばろう付けは不要
・接続部分の絶縁処理を怠ると、漏電や短絡の原因になる。技能試験では重大欠陥★
・接続部の抵抗を測るには、微小抵抗計を用いる
・接続の良否は、施工後の絶縁抵抗測定と導通試験で確認する

★ここだけ暗記
・抵抗を増加させない、強度を20パーセント以上減少させない★
・絶縁は電線の絶縁物と同等以上★
・接続器またはろう付けを用いる★
・接続部は必ずボックス内★
・テープ巻きは半幅重ねで2回以上（4層以上）`,
