　リングスリーブは工具と技能が必要ですが、差込形コネクタは電線を差し込むだけで接続が完了します。内部にばね状の金属片があり、差し込んだ電線を押さえつけて保持し、同時に電気的な接触も確保します。工具が不要で、施工が速く、誰がやっても同じ品質になるのが利点です。近年の住宅工事では主流になっています。
　差込形コネクタは、接続できる電線の本数によって2本用、3本用、4本用、5本用などがあります。透明な樹脂でできていて、外から電線が奥まで入っているかを確認できるようになっています。使用できる電線は、原則として単線です。より線に使えるタイプもありますが、製品の仕様に従う必要があります。★
　このほか、接続に使う材料には圧着端子、絶縁キャップ、ボルト形コネクタ、電線コネクタなどがあります。それぞれの用途を整理しておきましょう。

