　選定の判断軸は四つあります。第一に機械的な強度が要るか。人や車がぶつかる、物が当たるおそれのある場所では金属管が有利です。第二に腐食のおそれがあるか。薬品や水気のある場所では合成樹脂管が有利です。第三に屈曲が多いか。振動する機器の近くや曲がりくねった経路では可とう管が要ります。第四に火災に対する配慮。自己消火性のない管は使用場所が限られます。
