　名前は英語由来のものが多く、意味を知ると覚えやすくなります。カップリングは「つなぐもの」、ブッシングは「詰め物」、ロックナットは「締め付けるナット」、エントランスキャップは「入口のふた」といった具合です。用途とセットで覚えていきましょう。
