　電線が数本ならば管に通せばすみますが、ビルの幹線のように何十本もの電線を通す場合、管では効率が悪すぎます。そこで、大きな断面の通路をつくり、そこに電線をまとめて収める工事方法があります。それがダクト工事とケーブルラック工事です。
　ダクトには目的別にいくつもの種類があり、名前が似ているので混乱しやすい部分です。金属ダクト、バスダクト、ライティングダクト、フロアダクト、セルラダクト、金属線ぴ。それぞれ何を通すためのものかを押さえれば、区別できます。
　金属ダクトは絶縁電線を多数収める通路。バスダクトは電線ではなく導体（ブスバー）そのものを収めた大電流用の幹線。ライティングダクトは照明器具を任意の位置に取り付けられるレール。フロアダクトは床の中に埋め込んで配線を通すもの。金属線ぴは細い樋のようなもので、少数の電線を通します。★

