　一方、ケーブルを支持する部品には、ステープル、サドル、ケーブルタイ、ケーブルラックなどがあります。それぞれ対象と使い方が決まっており、鑑別で名称と用途を答えさせる出題があります。とくにステープル（VVFケーブル用のコの字形の釘）とサドル（管を留める金具）の使い分けは頻出です。★

