　鑑別問題は、工具や材料の写真を見て、名称または用途を答える形式です。知っていれば数秒で解け、知らなければどうにもならない、はっきりした問題です。だからこそ、ここは確実に取りにいくべき分野です。この節では、これまで学んだ工具を作業ごとに並べ直し、写真を見たときに何を手がかりに判断するかを整理します。
　判断の手がかりは三つあります。第一に形。円筒形の刃ならホルソ、円錐形ならリーマ、U字形のハンドルならクリックボール。第二に色。圧着ペンチの黄色と赤色は決定的な違いです。第三に付属品。補助接地棒が付いていれば接地抵抗計、テストリードだけなら絶縁抵抗計や回路計です。
　そして最後に、その工具が「何をする道具か」を一言で言えるようにしておくこと。鑑別では用途を問われることが多いからです。★

