　ケーブルは外装によって機械的に保護されているため、施設場所の制限がありません。展開した場所、点検できる隠ぺい場所、点検できない隠ぺい場所、乾燥した場所、湿気の多い場所、水気のある場所、屋外、屋側、地中、そのすべてに施設できます。この万能性が最大の特長です。★
