　大きなビルや工場では、幹線に数百アンペア、ときには数千アンペアの電流が流れます。これを電線でまかなおうとすると、非常に太い電線を何本も並べることになり、施工も曲げも大変です。そこで、帯状の銅やアルミの導体を絶縁物で支持し、金属の外箱に収めたものが使われます。これがバスダクトです。
　バスダクトは電線ではなく、導体そのものを収めた製品です。ここが金属ダクトとの決定的な違いで、試験でも繰り返し問われます。金属ダクトは「電線を通す通路」、バスダクトは「導体を組み込んだ幹線そのもの」です。★
　バスダクトの利点は、大電流を安全に流せること、断面が小さくてすむこと、分岐が容易なことです。プラグインバスダクトなら、必要な位置で分岐ユニットを差し込んで電源を取り出せるので、工場のレイアウト変更にも柔軟に対応できます。

