　事務所のように、部屋の中央に机が並ぶ空間では、壁から配線するだけでは電源が届きません。そこで、床の中や床の表面に配線して、必要な位置で電源を取り出す工事方法が用意されています。それがフロアダクト工事、セルラダクト工事、そして平形保護層工事です。
　フロアダクトはコンクリートの床に埋め込む金属製のダクト、セルラダクトは床の構造材である鋼製デッキプレートの溝を利用したダクトです。どちらも新築時に床とともに施工するもので、後からの変更は困難です。
　これに対し、平形保護層工事は、平たいケーブル（フラットケーブル）を保護層で覆って、カーペットの下などに敷設する方法です。既設の床に後から配線できるのが利点ですが、施設できる場所と条件は厳しく限定されています。★

