　覚え方の骨格はこうです。まず、どこにでも施設できる三つ（ケーブル工事、金属管工事、合成樹脂管工事）を覚える。次に、可とう電線管工事（2種）もほぼ同じだと覚える。残りは制限がある、と考えます。
