　低圧の屋内配線では、使用電圧が300V以下か300Vを超えるかで、要求される施工の内容が変わります。300Vという数字は、感電したときの危険度が一段上がる境目として設けられたものです。試験でも、この境目を意識した出題が繰り返されます。
　なぜ300Vなのかというと、低圧の区分（交流600V以下）のなかで、家庭や小規模事業所で一般的に使われる100Vや200Vの回路と、工場などで使われる400V級の回路とを分けるためです。400V級は感電したときの危険が大きく、絶縁の破壊も起こりやすいので、接地や施設場所の制限が厳しくなります。
　押さえるべきポイントは三つです。接地工事の種類が変わること。施設できる工事方法が変わること。絶縁抵抗の基準値が変わること。順に見ていきましょう。★

