　玄関の呼び鈴、インターホン、出退表示灯、火災報知設備の一部など、ごく小さな電力しか使わない回路があります。これらは電圧も電流も小さく、感電や火災の危険が低いため、通常の低圧屋内配線より緩やかな規定が適用されます。これを小勢力回路といいます。
