・地中箱（ハンドホール）を設ける場合は、ふたが容易に外れない構造とする
・工事費は安いが、後からの引き替えが困難という欠点がある★

【図解】地中埋設の三方式
　方式｜内容｜特徴
　管路式｜管を埋めてケーブルを通す★｜引き替えが容易★
　暗きょ式｜洞道やトラフに収める★｜多条敷設と点検が容易★
　直接埋設式｜ケーブルを直接埋める★｜安いが引き替えが困難★
