　電気機器の内部で絶縁が劣化し、金属製の外箱に電気が漏れたとします。もし外箱が大地とつながっていなければ、外箱には電圧が加わったままになります。そこに人が触れると、人体を通って大地へ電流が流れ、感電します。
　ところが、外箱をあらかじめ低い抵抗で大地につないでおけば、漏れた電流は人体よりはるかに抵抗の小さい接地線を通って大地へ流れます。人体に流れる電流はごくわずかになり、感電を防げます。さらに、大きな地絡電流が流れることで漏電遮断器が動作し、電源が切れます。これが接地工事の目的です。★
　接地工事にはA種、B種、C種、D種の四種類があり、対象と接地抵抗値が定められています。第二種電気工事士では、とくにC種とD種が重要です。

